from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import KnowledgeBaseArticle

class ArticleTranslationUpdateView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def put(self, request, article_id):
        lang = request.data.get("language")
        content = request.data.get("content")

        # Scope article lookup to user's organization
        article = KnowledgeBaseArticle.objects.filter(id=article_id, organization=request.user.organization).first()
        if not article:
            return Response({"error": "Article not found"}, status=status.HTTP_404_NOT_FOUND)

        target_field = f"body_{lang}"
        if not hasattr(article, target_field):
            return Response({"error": "Unsupported language"}, status=status.HTTP_400_BAD_REQUEST)

        setattr(article, target_field, content)
        article.save(update_fields=[target_field])
        return Response({"status": "Translation updated", "article_id": article_id, "language": lang})
